public class Main {
    static int[] arr = {1, 2, 3};
    static int n = 3;
    static boolean[] visited = new boolean[n];
    static int[] chosen = new int[n];

void permute(int depth) {
    if (depth == n) { print(); return; }
    for (int i = 0; i < n; i++) {
        if (visited[i]) continue;
        visited[i] = _____;
        chosen[depth] = arr[i];
        permute(depth + 1);
        visited[i] = _____;
    }
}

    public static void print() {
        for (int v : chosen) System.out.print(v + " ");
        System.out.println();
    }
    public static void main(String[] args) { permute(0); }
}
